@pytest.mark.parametrize("case", EDIT_CASES, ids=[c["id"] for c in EDIT_CASES])
def test_diagnostics_follow_each_edit_shape(run, workdir, case):
    """CATCHES: stale or missing publishDiagnostics after an edit, wrong ranges/messages
    for an error kind, or a server that stops serving a half-typed document."""
    S.check(run, workdir, case, __file__)


@pytest.mark.parametrize("case", CROSS_CASES, ids=[c["id"] for c in CROSS_CASES])
def test_dependency_edits_invalidate_importers(run, workdir, case):
    """CATCHES: an importer analysed against a stale dependency (buffer vs disk) or a
    dependency error reported differently from the reference."""
    S.check(run, workdir, case, __file__)


@pytest.mark.parametrize("case", POSITION_CASES, ids=[c["id"] for c in POSITION_CASES])
def test_position_edge_cases_per_request(run, workdir, case):
    """CATCHES: crashes or different answers for out-of-range, malformed or UTF-16
    positions and for documents that are not open."""
    S.check(run, workdir, case, __file__)


@pytest.mark.parametrize("case", COMPLETION_CASES, ids=[c["id"] for c in COMPLETION_CASES])
def test_completion_contexts(run, workdir, case):
    """CATCHES: completion lists that differ in items, kinds, details or order."""
    S.check(run, workdir, case, __file__)


@pytest.mark.parametrize("case", SYMBOL_CASES, ids=[c["id"] for c in SYMBOL_CASES])
def test_workspace_and_document_symbols(run, workdir, case):
    """CATCHES: symbol queries that match, order or locate symbols differently."""
    S.check(run, workdir, case, __file__)
